<?php
require_once "db.php"; require_login(); $uid=(int)$_SESSION["user_id"];
if($_SERVER["REQUEST_METHOD"]==="POST" && isset($_POST["resolve_id"])){
    $id=(int)$_POST["resolve_id"]; $stmt=$conn->prepare("UPDATE alerts SET status='Resolved' WHERE id=? AND user_id=?"); $stmt->bind_param("ii",$id,$uid); $stmt->execute(); flash("Alert marked as resolved."); header("Location: alert_history.php"); exit;
}
$stmt=$conn->prepare("SELECT id,alert_type,location_text,latitude,longitude,notes,status,alert_time FROM alerts WHERE user_id=? ORDER BY alert_time DESC"); $stmt->bind_param("i",$uid); $stmt->execute(); $rows=$stmt->get_result();
?>
