<section class="panel"><div class="panel-head"><div><h3>All alert records</h3><p class="muted"><?=$rows->num_rows?> record(s)</p></div></div><?php if($rows->num_rows): ?><div class="table-wrap"><table><thead><tr><th>Type / Time</th><th>Location</th><th>Note</th><th>Status</th><th>Action</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()): ?><tr><td><b><?=e($r["alert_type"])?></b><small><?=e($r["alert_time"])?></small></td><td><?php if($r["latitude"]!==null && $r["longitude"]!==null): ?><a target="_blank" rel="noopener" href="https://maps.google.com/?q=<?=e($r["latitude"])?>,<?=e($r["longitude"])?>">View map ↗</a><small><?=e($r["location_text"])?></small><?php else: ?><?=e($r["location_text"] ?: "Not shared")?><?php endif; ?></td><td><?=e($r["notes"] ?: "—")?></td><td><span class="pill <?=$r["status"]==="Resolved"?"resolved":"pending"?>"><?=e($r["status"])?></span></td><td><?php if($r["status"]!=="Resolved"): ?><form method="post"><input type="hidden" name="resolve_id" value="<?=$r["id"]?>"><button class="text-btn" type="submit">Mark resolved</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endwhile; ?></tbody></table></div><?php else: ?><div class="empty-state">◷<p>No alert records yet.</p><small>Create an SOS record to see it here.</small><a class="btn btn-small" href="sos.php">Create SOS record</a></div><?php endif; ?></section><p class="safety-disclaimer">Alert records are not monitored by emergency responders. Do not rely on this demo for real-time emergency assistance.</p></main></body></html>